INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 50, 'Y', 'Y', 
q'[

--GRAD ATHT12 WITH SGASTDN
SELECT RORALGS_AMT
FROM SGBSTDN X, SGRCHRT X, RORALGS, ROBINST
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SGBSTDN_COLL_CODE_1 = 'AH' THEN 'AH'
END = RORALGS_KEY_7

AND CASE -- major/program code
    WHEN X.SGBSTDN_PROGRAM_1 = 'ATHT12' THEN 'ATHT12'
END = RORALGS_KEY_9	

AND CASE -- cohort code
    WHEN X.SGRCHRT_CHRT_CODE = (ROBINST_AIDY_START_YEAR || 'AT') THEN (ROBINST_AIDY_START_YEAR || 'AT')              --2025 FOR FY26
	WHEN X.SGRCHRT_CHRT_CODE = (ROBINST_AIDY_END_YEAR || 'AT') THEN (ROBINST_AIDY_END_YEAR || 'AT')                  --2026 FOR FY26
END = RORALGS_KEY_11	
	
		-- max cohort term <= passed period
AND X.SGRCHRT_TERM_CODE_EFF = (
    SELECT MAX(Y.SGRCHRT_TERM_CODE_EFF)
    FROM SGRCHRT Y
    WHERE Y.SGRCHRT_PIDM = X.SGRCHRT_PIDM
    AND Y.SGRCHRT_TERM_CODE_EFF <= :PERIOD
)
-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = X.SGRCHRT_PIDM
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = ROBINST_AIDY_CODE
AND RORALGS_AIDY_CODE = :AIDY
-- END
]', 
TO_DATE('12/10/2025 13:06:57', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 60, 'Y', 'Y', 
q'[

--GRAD ATHT12 NO SGASTDN
SELECT RORALGS_AMT
FROM SARADAP X, SARAPPD X, SARCHRT, RORALGS, STVAPDC, ROBINST
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SARADAP_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SARADAP_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SARADAP_COLL_CODE_1 = 'AH' THEN 'AH'
END = RORALGS_KEY_7

AND CASE -- major/program code
    WHEN X.SARADAP_PROGRAM_1 = 'ATHT12' THEN 'ATHT12'
END = RORALGS_KEY_9	

--likely only need one of these for new students, but need to check witrh SLU
AND CASE -- cohort code
    WHEN SARCHRT_CHRT_CODE = (ROBINST_AIDY_START_YEAR || 'AT') THEN (ROBINST_AIDY_START_YEAR || 'AT')              --2025 FOR FY26
	WHEN SARCHRT_CHRT_CODE = (ROBINST_AIDY_END_YEAR || 'AT') THEN (ROBINST_AIDY_END_YEAR || 'AT')                  --2026 FOR FY26
END = RORALGS_KEY_11	
	
-- max saradap term <= passed period	
AND X.SARADAP_TERM_CODE_ENTRY = (
     SELECT MAX(Y.SARADAP_TERM_CODE_ENTRY)
    FROM SARADAP Y, ROBINST
    WHERE Y.SARADAP_PIDM = X.SARADAP_PIDM
	AND Y.SARADAP_TERM_CODE_ENTRY >= (ROBINST_AIDY_END_YEAR || '00')
    AND Y.SARADAP_TERM_CODE_ENTRY <= :PERIOD
	AND ROBINST_AIDY_CODE = :AIDY
)
--max application decision code sequence number
AND X.SARAPPD_SEQ_NO = (SELECT MAX (X.SARAPPD_SEQ_NO)
	FROM SARAPPD Y, ROBINST
	WHERE     Y.SARAPPD_PIDM = X.SARAPPD_PIDM
	AND Y.SARAPPD_SEQ_NO < 99
	AND Y.SARAPPD_TERM_CODE_ENTRY >= (ROBINST_AIDY_END_YEAR || '00')
	AND Y.SARAPPD_TERM_CODE_ENTRY <= :PERIOD
	AND ROBINST_AIDY_CODE = :AIDY           
	AND X.SARADAP_APPL_NO = Y.SARAPPD_APPL_NO) 
      
AND STVAPDC_INST_ACC_IND = 'Y'
AND STVAPDC_SIGNF_IND = 'Y'
		
AND X.SARAPPD_APDC_CODE = STVAPDC_CODE	
AND X.SARADAP_APPL_NO = X.SARAPPD_APPL_NO
AND X.SARADAP_APPL_NO = SARCHRT_APPL_NO
AND X.SARADAP_TERM_CODE_ENTRY = X.SARAPPD_TERM_CODE_ENTRY
AND X.SARADAP_TERM_CODE_ENTRY = SARCHRT_TERM_CODE_ENTRY
AND RORALGS_AIDY_CODE = ROBINST_AIDY_CODE
AND RORALGS_AIDY_CODE = :AIDY
AND X.SARADAP_PIDM = X.SARAPPD_PIDM
AND X.SARADAP_PIDM = SARCHRT_PIDM
AND X.SARADAP_PIDM = :PIDM
-- END
]', 
TO_DATE('12/10/2025 13:07:15', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 70, 'Y', 'Y', 
q'[
--GRAD PT MAJOR ENROLLED OR NOT ENROLLED WITH SGASTDN
SELECT RORALGS_AMT
FROM SGBSTDN X, RORALGS, SGRCHRT X, ROBINST
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SGBSTDN_COLL_CODE_1 = 'AH' THEN 'AH'
END = RORALGS_KEY_7

AND CASE -- major/program code
	WHEN X.SGBSTDN_MAJR_CODE_1 = 'PT' THEN 'PT'
END = RORALGS_KEY_9		
		
--NEED TO HAVE SIX ROWS ON RORALGS, A FALL AND SPRING ROW FOR EACH COHORT CODE 2026PT, 2027PT, AND ONE MORE FOR THE TRANSFER COHORT	
AND CASE -- cohort code
    WHEN X.SGRCHRT_CHRT_CODE = (ROBINST_AIDY_END_YEAR || 'PT') THEN (ROBINST_AIDY_END_YEAR || 'PT')                   --2027PT FOR FY27
    WHEN X.SGRCHRT_CHRT_CODE = (ROBINST_AIDY_START_YEAR || 'PT') THEN (ROBINST_AIDY_START_YEAR || 'PT')                 --2026PT FOR FY27
	--Janice will visit with Hayley about a cohort that transfers in
	--WHEN X.SGRCHRT_CHRT_CODE = ?? THEN ??
END = RORALGS_KEY_11		

AND CASE -- term
    WHEN (ROBINST_AIDY_END_YEAR || '10') = :PERIOD THEN 'FALL'
    WHEN (ROBINST_AIDY_END_YEAR || '20') = :PERIOD THEN 'SPRING'
END = RORALGS_KEY_12

-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD)

	-- max cohort term <= passed period
AND X.SGRCHRT_TERM_CODE_EFF = (
    SELECT MAX(Y.SGRCHRT_TERM_CODE_EFF)
    FROM SGRCHRT Y
    WHERE Y.SGRCHRT_PIDM = X.SGRCHRT_PIDM
    AND Y.SGRCHRT_TERM_CODE_EFF <= :PERIOD
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = X.SGRCHRT_PIDM
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = ROBINST_AIDY_CODE
AND RORALGS_AIDY_CODE = :AIDY
-- END

]', 
TO_DATE('12/10/2025 13:07:33', 'MM/DD/YYYY HH24:MI:SS')
);

