INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 90, 'Y', 'Y', 
q'[
--GRAD AH WITH MAJOR IN IN OCTH, MIT ENROLLED FULL TIME
SELECT CASE
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0) >= 12
        THEN RORALGS_AMT
    END as calc_amt
FROM SGBSTDN X, RORALGS
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SGBSTDN_COLL_CODE_1 = 'AH' THEN 'AH'
END = RORALGS_KEY_7

AND CASE -- major/program code
	WHEN X.SGBSTDN_MAJR_CODE_1 = 'OCTH' THEN 'OCTH'
	WHEN X.SGBSTDN_MAJR_CODE_1 = 'MIT' THEN 'MIT'
END = RORALGS_KEY_9		
	
AND RORALGS_KEY_12 = 'FT'
		
-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END
]', 
TO_DATE('12/10/2025 13:08:13', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 100, 'Y', 'Y', 
q'[
--GRAD AH WITH MAJOR IN IN OCTH, MIT ENROLLED PART TIME
SELECT CASE
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0) < 12
	AND  NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0) > 0
        THEN round(roralgs_amt * NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0))
    END as calc_amt
FROM SGBSTDN X, RORALGS
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SGBSTDN_COLL_CODE_1 = 'AH' THEN 'AH'
END = RORALGS_KEY_7

AND CASE -- major/program code
	WHEN X.SGBSTDN_MAJR_CODE_1 = 'OCTH' THEN 'OCTH'
	WHEN X.SGBSTDN_MAJR_CODE_1 = 'MIT' THEN 'MIT'
END = RORALGS_KEY_9		
	
AND RORALGS_KEY_12 = 'PT'
		
-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END

]', 
TO_DATE('12/10/2025 13:08:29', 'MM/DD/YYYY HH24:MI:SS')
);

