INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 240, 'Y', 'Y', 
q'[
--GRAD SE, BA, PS, G% ATTRIBUTES WITH SGASTDN
--DON'T NEED SEQUENCE FOR ENROLLED SINCE IT'S ALWAYS A FLAT RATE
SELECT RORALGS_AMT
FROM SGBSTDN X, SGRSATT X, RORALGS
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SGBSTDN_COLL_CODE_1 = 'SE' THEN 'SE'
    WHEN X.SGBSTDN_COLL_CODE_1 = 'BA' THEN 'BA'
	WHEN X.SGBSTDN_COLL_CODE_1 = 'PS' THEN 'PS'
END = RORALGS_KEY_7
	
AND CASE -- cohort code
    WHEN X.SGRSATT_ATTS_CODE = 'GG2' THEN 'GG2'
    WHEN X.SGRSATT_ATTS_CODE = 'GG3' THEN 'GG3'
	WHEN X.SGRSATT_ATTS_CODE = 'GG4' THEN 'GG4'
	WHEN X.SGRSATT_ATTS_CODE = 'GG5' THEN 'GG5'
	WHEN X.SGRSATT_ATTS_CODE = 'GGI2' THEN 'GGI2'
	WHEN X.SGRSATT_ATTS_CODE = 'GGI3' THEN 'GGI3'
END = RORALGS_KEY_10
	
-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
	--max attribute term <= passed term
AND X.SGRSATT_TERM_CODE_EFF = (
SELECT MAX(Y.SGRSATT_TERM_CODE_EFF)
    FROM SGRSATT Y
    WHERE Y.SGRSATT_TERM_CODE_EFF <= :PERIOD
	AND X.SGRSATT_PIDM =  Y.SGRSATT_PIDM
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = X.SGRSATT_PIDM
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
--END
]', 
TO_DATE('12/10/2025 13:12:46', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_GR', 250, 'Y', 'Y', 
q'[
--GRAD SE, BA, PS, G% ATTRIBUTES NO SGASTDN
SELECT RORALGS_AMT
FROM SARADAP X, SARAPPD X, SARAATT, RORALGS, STVAPDC
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SARADAP_LEVL_CODE = 'GR' THEN 'GR'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SARADAP_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
AND CASE -- college code
    WHEN X.SARADAP_COLL_CODE_1 = 'SE' THEN 'SE'
    WHEN X.SARADAP_COLL_CODE_1 = 'BA' THEN 'BA'
	WHEN X.SARADAP_COLL_CODE_1 = 'PS' THEN 'PS'
END = RORALGS_KEY_7
	
AND CASE -- cohort code
    WHEN SARAATT_ATTS_CODE = 'GG2' THEN 'GG2'
    WHEN SARAATT_ATTS_CODE = 'GG3' THEN 'GG3'
	WHEN SARAATT_ATTS_CODE = 'GG4' THEN 'GG4'
	WHEN SARAATT_ATTS_CODE = 'GG5' THEN 'GG5'
	WHEN SARAATT_ATTS_CODE = 'GGI2' THEN 'GGI2'
	WHEN SARAATT_ATTS_CODE = 'GGI3' THEN 'GGI3'
END = RORALGS_KEY_10
	
-- max saradap term <= passed period	
AND X.SARADAP_TERM_CODE_ENTRY = (
     SELECT MAX(Y.SARADAP_TERM_CODE_ENTRY)
    FROM SARADAP Y, ROBINST
    WHERE Y.SARADAP_PIDM = X.SARADAP_PIDM
	AND Y.SARADAP_TERM_CODE_ENTRY >= (ROBINST_AIDY_END_YEAR || '00')
    AND Y.SARADAP_TERM_CODE_ENTRY <= :PERIOD
	AND ROBINST_AIDY_CODE = :AIDY
)
--max application decision code sequence number
AND X.SARAPPD_SEQ_NO = (SELECT MAX (X.SARAPPD_SEQ_NO)
	FROM SARAPPD Y, ROBINST
	WHERE     Y.SARAPPD_PIDM = X.SARAPPD_PIDM
	AND Y.SARAPPD_SEQ_NO < 99
	AND Y.SARAPPD_TERM_CODE_ENTRY >= (ROBINST_AIDY_END_YEAR || '00')
	AND Y.SARAPPD_TERM_CODE_ENTRY <= :PERIOD
	AND ROBINST_AIDY_CODE = :AIDY           
	AND X.SARADAP_APPL_NO = Y.SARAPPD_APPL_NO) 
      
AND STVAPDC_INST_ACC_IND = 'Y'
AND STVAPDC_SIGNF_IND = 'Y'
		
AND X.SARAPPD_APDC_CODE = STVAPDC_CODE	
AND X.SARADAP_APPL_NO = X.SARAPPD_APPL_NO
AND X.SARADAP_APPL_NO = SARAATT_APPL_NO
AND X.SARADAP_TERM_CODE_ENTRY = X.SARAPPD_TERM_CODE_ENTRY
AND X.SARADAP_TERM_CODE_ENTRY = SARAATT_TERM_CODE
AND RORALGS_AIDY_CODE = :AIDY
AND X.SARADAP_PIDM = X.SARAPPD_PIDM
AND X.SARADAP_PIDM = SARAATT_PIDM
AND X.SARADAP_PIDM = :PIDM
--END
]', 
TO_DATE('12/10/2025 13:13:04', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
