	WHEN X.SGBSTDN_PROGRAM_1 = 'EDL225' THEN 'EDL225'         --$990 for FY26
	
	WHEN X.SGBSTDN_PROGRAM_1 = 'EDF22' THEN 'EDF22'         --$1,400 for FY26
	WHEN X.SGBSTDN_PROGRAM_1 = 'EDHA22' THEN 'EDHA22'         --$1,400 for FY26
	WHEN X.SGBSTDN_PROGRAM_1 = 'EDI21' THEN 'EDI21'         --$1,400 for FY26
	WHEN X.SGBSTDN_PROGRAM_1 = 'EDL24' THEN 'EDL24'         --$1,400 for FY26
	WHEN X.SGBSTDN_PROGRAM_1 = 'EDS22' THEN 'EDS22'         --$1,400 for FY26
	WHEN X.SGBSTDN_PROGRAM_1 = 'EPE21' THEN 'EPE21'         --$1,400 for FY26
	WHEN X.SGBSTDN_PROGRAM_1 = 'UNCL883' THEN 'UNCL883'         --$1,400 for FY26
END = RORALGS_KEY_9		
		
-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END
]', 
TO_DATE('12/10/2025 13:14:29', 'MM/DD/YYYY HH24:MI:SS')
);

