INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_MR', 70, 'Y', 'Y', 
q'[
-- MADRID UNDERGRAD NOT ENROLLED NO SGASTDN
SELECT RORALGS_AMT --assume full time
FROM SARADAP a
CROSS JOIN RORALGS
INNER JOIN SPRIDEN s 
    ON s.SPRIDEN_PIDM = a.SARADAP_PIDM AND s.SPRIDEN_CHANGE_IND IS NULL
INNER JOIN SARAPPD b
    ON b.SARAPPD_PIDM = a.SARADAP_PIDM
    AND b.SARAPPD_TERM_CODE_ENTRY = a.SARADAP_TERM_CODE_ENTRY
    AND b.SARAPPD_APPL_NO = a.SARADAP_APPL_NO 
INNER JOIN STVAPDC c
    ON c.STVAPDC_CODE = b.SARAPPD_APDC_CODE
INNER JOIN ROBINST r
    ON r.ROBINST_AIDY_CODE = :AIDY
LEFT JOIN SARAATT d
    ON d.SARAATT_PIDM = a.SARADAP_PIDM
    AND d.SARAATT_APPL_NO = a.SARADAP_APPL_NO
    AND d.SARAATT_TERM_CODE = a.SARADAP_TERM_CODE_ENTRY
WHERE RORALGS_KEY_1 = 'PBDG'
AND RORALGS_KEY_4 = '1TUI' -- budget component
AND CASE -- level code
    WHEN a.SARADAP_LEVL_CODE = 'UG' THEN 'UG'
END = RORALGS_KEY_5
AND CASE -- campus code
    WHEN a.SARADAP_CAMP_CODE = 'SP' THEN 'SP'
END = RORALGS_KEY_6
--SPTR ATTRIBUTE ONLY STAYS ACTIVE FOR FIRST TERM	
AND CASE -- attribute code
    WHEN d.SARAATT_ATTS_CODE = 'SPTR' THEN 'SPTR'
	WHEN (d.SARAATT_ATTS_CODE = 'SPDE' OR d.SARAATT_ATTS_CODE IS NULL) THEN 'SPDE'
END = RORALGS_KEY_10
AND RORALGS_KEY_12 = 'FT'

-- maa.SARADAP term <= passed period
AND a.SARADAP_TERM_CODE_ENTRY = (
    SELECT MAX(SARADAP_TERM_CODE_ENTRY)
    FROM SARADAP
    WHERE SARADAP_PIDM = a.SARADAP_PIDM
    AND SARADAP_TERM_CODE_ENTRY >= (r.ROBINST_AIDY_END_YEAR || '00')   	
	AND SARADAP_TERM_CODE_ENTRY <= :PERIOD
)
--max application decision code sequence number
AND b.SARAPPD_SEQ_NO = (
    SELECT MAX (SARAPPD_SEQ_NO)
    FROM SARAPPD
    WHERE SARAPPD_PIDM = b.SARAPPD_PIDM
    AND SARAPPD_SEQ_NO < 99
    AND SARAPPD_TERM_CODE_ENTRY >= (r.ROBINST_AIDY_END_YEAR || '00')
    AND SARAPPD_TERM_CODE_ENTRY <= :PERIOD
    AND SARAPPD_APPL_NO = b.SARAPPD_APPL_NO
) 
AND RORALGS_AIDY_CODE = :AIDY
AND a.SARADAP_PIDM = :PIDM
]', 
TO_DATE('12/17/2025 15:14:18', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '1TUI_MR', 80, 'Y', 'Y', 
q'[
--SPSA ENROLLED 12-18 HOURS 
SELECT CASE
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0) >= 12
	AND  NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0) <= 18
        THEN RORALGS_AMT
    END as calc_amt
FROM SGBSTDN X, RORALGS, SGRSATT X
WHERE RORALGS_KEY_1 = 'PBDG'

AND RORALGS_KEY_4 = '1TUI' -- budget component

AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'UG' THEN 'UG'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
--attribute for Madrid study abroad
AND CASE -- attribute code
    WHEN X.SGRSATT_ATTS_CODE = 'SPSA' THEN 'SPSA'
END = RORALGS_KEY_10
		
AND RORALGS_KEY_12 = '12to18'
	
--max attribute term <= passed term	
AND X.SGRSATT_TERM_CODE_EFF = (
SELECT MAX(Y.SGRSATT_TERM_CODE_EFF)
    FROM SGRSATT Y
    WHERE Y.SGRSATT_TERM_CODE_EFF <= :PERIOD
	AND X.SGRSATT_PIDM =  Y.SGRSATT_PIDM
)
-- max sgbstdn term <= passed period
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = X.SGRSATT_PIDM
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END
]', 
TO_DATE('12/10/2025 13:21:25', 'MM/DD/YYYY HH24:MI:SS')
);

