    WHEN X.SARADAP_LEVL_CODE = 'UG' THEN 'UG'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SARADAP_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
	
--attribute for Madrid study abroad
AND CASE -- attribute code
    WHEN SARAATT_ATTS_CODE = 'SPSA' THEN 'SPSA'
END = RORALGS_KEY_10
		
