INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '23PF', 10, 'Y', 'Y', 
q'[
-- PKTF PERIOD BUDGET RULE - written by JD 10/3/2025
-- Parks Tech Fee (previously PARKS_TECH_FEE)
SELECT CASE
    -- full time
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, a.SGBSTDN_PIDM, 'N'), 0) >= 12 
        THEN RORALGS_AMT 
    -- part time
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, a.SGBSTDN_PIDM, 'N'), 0)
        BETWEEN 0 AND 11 THEN ROUND((RORALGS_AMT / 2))
    END as calc_amt
FROM SGBSTDN a, RORALGS
WHERE RORALGS_KEY_1 = 'PBDG'
AND RORALGS_KEY_4 = '23PF' -- budget component
AND RORALGS_KEY_5 = 'UG' -- student level
AND CASE -- college code
    WHEN a.SGBSTDN_COLL_CODE_1 = 'SE' THEN 'SE'
END = RORALGS_KEY_7
AND a.SGBSTDN_TERM_CODE_EFF = ( -- max sgbstdn term <= passed period
    SELECT MAX(z.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN z
    WHERE z.SGBSTDN_PIDM = a.SGBSTDN_PIDM
    AND z.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND a.SGBSTDN_CAMP_CODE = 'FR'
AND a.SGBSTDN_PIDM = :PIDM
-- END
]', 
TO_DATE('12/17/2025 16:36:34', 'MM/DD/YYYY HH24:MI:SS')
);

