q'[
-- LAW SEQUENCES ===============================================================
-- sequence 400 - LAW FT
SELECT 
    CASE WHEN 
        NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(a.SGBSTDN_TERM_CODE_EFF, a.SGBSTDN_PIDM, 'N'), 0) >= 12
    THEN RORALGS_AMT
END
FROM SGBSTDN a, RORALGS
WHERE RORALGS_KEY_1 = 'PBDG' 
AND RORALGS_KEY_4 = '2FEE'
AND CASE
    WHEN a.SGBSTDN_LEVL_CODE = 'PL' THEN 'PL'
END = RORALGS_KEY_5
-- sgbstdn term
AND a.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN
    WHERE SGBSTDN_PIDM = a.SGBSTDN_PIDM
    AND SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
AND a.SGBSTDN_STST_CODE IN  ('AS','IL')
AND RORALGS_AIDY_CODE = :AIDY
AND a.SGBSTDN_PIDM = :PIDM
-- ;
]', 
TO_DATE('12/10/2025 13:25:24', 'MM/DD/YYYY HH24:MI:SS')
);

