INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '3HSM', 50, 'Y', 'Y', 
q'[
--UNDERGRAD FRESHMEN NOT ENROLLED NO SGASTDN
SELECT RORALGS_AMT
FROM SARADAP X, SARAPPD X, RORALGS, STVAPDC, RORPRST
WHERE RORALGS_KEY_1 = 'PBDG'

AND CASE -- freshmen student type
    WHEN X.SARADAP_STYP_CODE = 'F' THEN 'F' 
END = RORALGS_KEY_2 

AND RORALGS_KEY_4 = '3HSM' -- budget component                 

AND CASE -- level code
    WHEN X.SARADAP_LEVL_CODE = 'UG' THEN 'UG'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN X.SARADAP_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
		
-- max saradap term <= passed period	
AND X.SARADAP_TERM_CODE_ENTRY = (
     SELECT MAX(Y.SARADAP_TERM_CODE_ENTRY)
    FROM SARADAP Y, ROBINST
    WHERE Y.SARADAP_PIDM = X.SARADAP_PIDM
    AND Y.SARADAP_CAMP_CODE = 'FR' 
	AND Y.SARADAP_TERM_CODE_ENTRY >= (ROBINST_AIDY_END_YEAR || '00')
    AND Y.SARADAP_TERM_CODE_ENTRY <= :PERIOD
	AND ROBINST_AIDY_CODE = :AIDY
)
--max application decision code sequence number
AND X.SARAPPD_SEQ_NO = (SELECT MAX (X.SARAPPD_SEQ_NO)
             FROM SARAPPD Y, ROBINST
              WHERE     Y.SARAPPD_PIDM = X.SARAPPD_PIDM
              AND Y.SARAPPD_SEQ_NO < 99
              AND Y.SARAPPD_TERM_CODE_ENTRY = X.SARADAP_TERM_CODE_ENTRY
              -- AND Y.SARAPPD_TERM_CODE_ENTRY >= (ROBINST_AIDY_END_YEAR || '00')
              -- AND Y.SARAPPD_TERM_CODE_ENTRY <= :PERIOD
              AND ROBINST_AIDY_CODE = :AIDY           
              AND X.SARADAP_APPL_NO = Y.SARAPPD_APPL_NO) 
      
   AND STVAPDC_INST_ACC_IND = 'Y'
   AND STVAPDC_SIGNF_IND = 'Y'

AND (RORPRST_XHS_LOCK_IND <> 'Y' OR RORPRST_XHS IS NULL)  
AND X.SARADAP_PIDM = RORPRST_PIDM
AND RORPRST_PERIOD = :PERIOD
AND X.SARAPPD_APDC_CODE = STVAPDC_CODE	
AND X.SARADAP_APPL_NO = X.SARAPPD_APPL_NO
AND X.SARADAP_TERM_CODE_ENTRY = X.SARAPPD_TERM_CODE_ENTRY
AND RORALGS_AIDY_CODE = :AIDY
AND X.SARAPPD_PIDM = X.SARADAP_PIDM	
AND X.SARADAP_PIDM = :PIDM
-- END
]', 
TO_DATE('12/16/2025 15:58:27', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '3HSM', 60, 'Y', 'Y', 
q'[
--UNDERGRAD TRANSFER ENROLLED WITH SGASTDN AND CHANGED SGASTDN RECORD AFTER FIRST TERM
SELECT CASE
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, Y.SGBSTDN_PIDM, 'N'), 0) >= RORCRHR_HALF_TIME_CR_HRS
        THEN RORALGS_AMT
    END as calc_amt
FROM SGBSTDN X, SGBSTDN Y, RORCRHR, RORALGS, ROBNYUD
WHERE RORALGS_KEY_1 = 'PBDG'

AND CASE -- freshmen student type
    WHEN (X.SGBSTDN_STYP_CODE IN ('1','T')) THEN 'T' 
END = RORALGS_KEY_2 

AND RORALGS_KEY_4 = '3HSM' -- budget component                        

AND CASE -- level code
    WHEN Y.SGBSTDN_LEVL_CODE = 'UG' THEN 'UG'
END = RORALGS_KEY_5
	
AND CASE -- campus code
    WHEN Y.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
		
-- max sgbstdn term <= passed period
AND Y.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y1.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y1
    WHERE Y1.SGBSTDN_PIDM = Y.SGBSTDN_PIDM
    AND Y1.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)
-- has transfer sgastdn record in the aid year	
AND X.SGBSTDN_TERM_CODE_EFF BETWEEN TRIM(TO_CHAR ('20'||SUBSTR(:AIDY, 3,2) || '00')) AND TRIM(TO_CHAR ('20'||SUBSTR(:AIDY, 3,2)+1 || '00'))	
 AND X.SGBSTDN_STYP_CODE IN ('1','T') 
  AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1') 

  AND Y.SGBSTDN_TERM_CODE_EFF > X.SGBSTDN_TERM_CODE_EFF
  AND Y.SGBSTDN_LEVL_CODE = 'UG'
  AND Y.SGBSTDN_STST_CODE IN  ('AS','IL','P1')

AND RORCRHR_AIDY_CODE = :AIDY
AND RORCRHR_LEVL_CODE = Y.SGBSTDN_LEVL_CODE
AND RORCRHR_PERIOD = :PERIOD

AND ROBNYUD_VALUE_120 = 'C'
AND X.SGBSTDN_PIDM = ROBNYUD_PIDM 

AND X.SGBSTDN_PIDM = Y.SGBSTDN_PIDM
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END

]', 
TO_DATE('12/10/2025 14:11:47', 'MM/DD/YYYY HH24:MI:SS')
);

