    TRIM(TO_CHAR ('20'||SUBSTR(:AIDY, 3,2)+1 || '00'))	
AND X.SGBSTDN_STYP_CODE IN ('1','T') 
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1') 
AND Y.SGBSTDN_TERM_CODE_EFF > X.SGBSTDN_TERM_CODE_EFF
AND Y.SGBSTDN_LEVL_CODE = 'UG'
AND Y.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND RORCRHR_AIDY_CODE = :AIDY
AND RORCRHR_LEVL_CODE = Y.SGBSTDN_LEVL_CODE
AND RORCRHR_PERIOD = :PERIOD
AND X.SGBSTDN_PIDM = ROBNYUD_PIDM 
AND X.SGBSTDN_PIDM = Y.SGBSTDN_PIDM
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END
]', 
TO_DATE('12/10/2025 14:18:14', 'MM/DD/YYYY HH24:MI:SS')
);

INSERT INTO FAISMGR.RBRABRC (
RBRABRC_AIDY_CODE, RBRABRC_ABRC_CODE, RBRABRC_SEQ_NO, RBRABRC_ACTIVE_IND, 
RBRABRC_VALIDATED_IND, RBRABRC_SQL_STATEMENT, RBRABRC_ACTIVITY_DATE
) VALUES (
'2627', '6LIV', 40, 'Y', 'Y', 
q'[
--UNDERGRAD TRANSFER PS,PL,NR041,TEAC03 ENROLLED WITH SGASTDN
SELECT CASE
    WHEN NVL(ROKMISC.F_CALC_STUD_CREDIT_HRS(:PERIOD, X.SGBSTDN_PIDM, 'N'), 0) >= RORCRHR_HALF_TIME_CR_HRS
        THEN (RORALGS_AMT + 300)
    END as calc_amt
FROM SGBSTDN X, RORCRHR, RORALGS, ROBNYUD
WHERE RORALGS_KEY_1 = 'PBDG'
AND RORALGS_KEY_4 = '6LIV'
AND CASE -- transfer student type
    WHEN (X.SGBSTDN_STYP_CODE IN ('1','T')) THEN 'T'                   
END = RORALGS_KEY_2 

AND CASE -- OFF CAMPUS HOUSING FLAG IN ROBNYUD
    WHEN ROBNYUD_VALUE_120 IS NULL THEN '1'  --off campus 
	WHEN (ROBNYUD_VALUE_120 NOT IN ('C','D')) THEN '1'  --off campus 
	WHEN ROBNYUD_VALUE_120 = 'D' THEN '3'  --with family/relative
END = RORALGS_KEY_3
AND CASE -- level code
    WHEN X.SGBSTDN_LEVL_CODE = 'UG' THEN 'UG'
END = RORALGS_KEY_5	
AND CASE -- campus code
    WHEN X.SGBSTDN_CAMP_CODE = 'FR' THEN 'FR'
END = RORALGS_KEY_6
AND X.SGBSTDN_TERM_CODE_EFF = (
    SELECT MAX(Y.SGBSTDN_TERM_CODE_EFF)
    FROM SGBSTDN Y
    WHERE Y.SGBSTDN_PIDM = X.SGBSTDN_PIDM
    AND Y.SGBSTDN_TERM_CODE_EFF <= :PERIOD
)	
AND RORCRHR_AIDY_CODE = :AIDY
AND RORCRHR_LEVL_CODE = X.SGBSTDN_LEVL_CODE
AND RORCRHR_PERIOD = :PERIOD
AND (
    X.SGBSTDN_COLL_CODE_1 IN ('PS','PL')                      
    OR X.SGBSTDN_PROGRAM_1  IN ('NR041','NR02','TEAC03')
)   
AND X.SGBSTDN_PIDM = ROBNYUD_PIDM 
AND X.SGBSTDN_STST_CODE IN  ('AS','IL','P1')
AND X.SGBSTDN_PIDM = :PIDM
AND RORALGS_AIDY_CODE = :AIDY
-- END
]', 
TO_DATE('12/17/2025 09:42:01', 'MM/DD/YYYY HH24:MI:SS')
);

